class MailyInstruction33Round9StateEvaluator(BaseEvaluator):
    """Evaluate human and automatic runs with one identical durable ruleset."""

    RULESET_SHA256 = RULESET_SHA256
    DEFAULT_API_BASE_URL = "http://127.0.0.1:8081"
    DEFAULT_TIMEOUT_SECONDS = 5.0
    DEFAULT_POLL_INTERVAL_SECONDS = 1.0

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")
        udid = str(
            params.get("udid")
            or getattr(getattr(controller, "runtime", None), "udid", "")
            or ""
        ).strip()
        base_metadata = {
            "task_id": TASK_ID,
            "read_only": True,
            "ruleset_sha256": RULESET_SHA256,
            "ruleset_spec": RULESET_SPEC,
            "step_groups": list(STEP_GROUPS),
            "checkpoint_specs": list(CHECKPOINT_SPECS),
            "evidence_policy": {
                "manual_and_automatic_share_ruleset": True,
                "trajectory_used": False,
                "run_dir_used": False,
                "final_ui_required": False,
                "final_ui_reason": "The terminal requirement is durable mail delivery, not a named final page.",
            },
        }
        if not udid:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="evaluation.params.udid is required; no simulator fallback is allowed",
                metadata={**base_metadata, "error": "missing_udid"},
            )

        expected_ruleset = str(params.get("expected_ruleset_sha256") or "").strip()
        if expected_ruleset and expected_ruleset != RULESET_SHA256:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="Configured evaluator ruleset digest does not match the loaded evaluator",
                metadata={
                    **base_metadata,
                    "expected_ruleset_sha256": expected_ruleset,
                    "observed_ruleset_sha256": RULESET_SHA256,
                },
            )

        api_base_url = str(params.get("api_base_url") or self.DEFAULT_API_BASE_URL).rstrip("/")
        bundle_id = str(params.get("bundle_id") or BUNDLE_ID).strip()
        expected_device_type = str(
            params.get("expected_ios_device_type_identifier")
            or EXPECTED_DEVICE_TYPE_IDENTIFIER
        ).strip()
        timeout_seconds = float(params.get("timeout_seconds", self.DEFAULT_TIMEOUT_SECONDS) or 0.0)
        poll_interval_seconds = float(
            params.get("poll_interval_seconds", self.DEFAULT_POLL_INTERVAL_SECONDS) or 0.0
        )
        evaluation_cutoff = datetime.now(timezone.utc)
        deadline = time.monotonic() + max(timeout_seconds, 0.0)
        last_result: EvalResult | None = None

        while True:
            try:
                last_result = self._evaluate_once(
                    api_base_url=api_base_url,
                    udid=udid,
                    bundle_id=bundle_id,
                    expected_device_type=expected_device_type,
                    evaluation_cutoff=evaluation_cutoff,
                    base_metadata=base_metadata,
                )
            except Exception as exc:
                return EvalResult(
                    status=EvalStatus.ERROR,
                    message=f"Read-only Maily evaluation failed: {type(exc).__name__}: {exc}",
                    metadata={
                        **base_metadata,
                        "api_base_url": api_base_url,
                        "udid": udid,
                        "exception_type": type(exc).__name__,
                    },
                )
            if last_result.status is EvalStatus.PASS or time.monotonic() >= deadline:
                return last_result
            if poll_interval_seconds > 0:
                time.sleep(poll_interval_seconds)

    def _evaluate_once(
        self,
        *,
        api_base_url: str,
        udid: str,
        bundle_id: str,
        expected_device_type: str,
        evaluation_cutoff: datetime,
        base_metadata: Mapping[str, Any],
    ) -> EvalResult:
        simulator_info = self._read_simulator_info(udid)
        booted_at = self._parse_required_datetime(
            simulator_info.get("lastBootedAt") or DEFAULT_WINDOW_START,
            field="window_start",
        )
        runtime_check = {
            "name": "bound_maily_runtime",
            "steps": list(range(1, 77)),
            "pass": (
                _simulator_matches_expected_device(
                    simulator_info, expected_device_type
                )
            ),
            "expected": {
                "deviceTypeIdentifier": expected_device_type,
                "state": "Booted",
            },
            "observed": simulator_info,
        }

        app_health = self._read_app_health(udid=udid, bundle_id=bundle_id)
        app_check = {
            "name": "maily_app_data_health",
            "steps": list(range(1, 77)),
            "pass": all(
                bool(app_health.get(key))
                for key in (
                    "container_resolved",
                    "metadata_bundle_matches",
                    "preferences_found",
                    "not_first_run",
                    "next_uids_info_present",
                    "next_uids_info_has_accounts",
                )
            ),
            "observed": app_health,
        }

        mailbox_names = sorted(
            {spec["mailbox"] for spec in MESSAGE_SPECS} | {SENDER_EMAIL}
        )
        mailboxes = {
            mailbox: self._fetch_mailbox_messages(
                api_base_url=api_base_url,
                recipient_email=mailbox,
            )
            for mailbox in mailbox_names
        }
        seed_check = self._check_seed_messages(mailboxes[SENDER_EMAIL])

        message_checks: list[dict[str, Any]] = []
        matched: dict[str, dict[str, Any]] = {}
        for spec in MESSAGE_SPECS:
            check, parsed = self._check_message(
                spec=spec,
                rows=mailboxes[spec["mailbox"]],
                booted_at=booted_at,
                evaluation_cutoff=evaluation_cutoff,
            )
            message_checks.append(check)
            if parsed is not None:
                matched[spec["key"]] = parsed

        order_check = self._check_business_order(matched)
        checks = [runtime_check, app_check, seed_check, *message_checks, order_check]
        failures = [check for check in checks if not check.get("pass")]
        step_coverage = self._build_step_coverage(
            message_checks=message_checks,
            order_check=order_check,
        )
        metadata = {
            **dict(base_metadata),
            "api_base_url": api_base_url,
            "udid": udid,
            "bundle_id": bundle_id,
            "evaluation_cutoff": evaluation_cutoff.isoformat(),
            "simulator_booted_at": booted_at.isoformat(),
            "checks": checks,
            "step_coverage": step_coverage,
            "mailbox_subjects": {
                mailbox: [str(row.get("subject") or "") for row in rows]
                for mailbox, rows in mailboxes.items()
            },
            "failures": failures,
        }
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Maily3 current-session state is missing or contradicts required evidence",
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.PASS,
            message="Maily3 current-session mail data, attachments, and business order all match",
            metadata=metadata,
        )

    @staticmethod
    def _build_step_coverage(
        *,
        message_checks: Sequence[Mapping[str, Any]],
        order_check: Mapping[str, Any],
    ) -> list[dict[str, Any]]:
        checks_by_name = {str(check.get("name") or ""): check for check in message_checks}
        result: list[dict[str, Any]] = []
        for spec in MESSAGE_SPECS:
            checkpoint_name = f"message:{spec['key']}"
            message_pass = checks_by_name.get(checkpoint_name, {}).get("pass") is True
            combined_pass = message_pass and order_check.get("pass") is True
            source_basis = (
                "Exact normalized In-Reply-To/References bind the requested seed; the exact "
                "MIME attachment hash binds the selected source asset."
                if spec.get("source_message_id")
                else "Exact current-session sender/recipient/subject/body plus Date and UID order "
                "bind the composed submission."
            )
            for step in spec["steps"]:
                result.append(
                    {
                        "step": int(step),
                        "pass": combined_pass,
                        "checkpoint_names": [checkpoint_name, "current_session_business_order"],
                        "dimensions": {
                            "final_object": f"Exactly one current-session {spec['subject']} delivery",
                            "content": "Exact sender, recipient, subject, body, and attachment contract",
                            "source_or_process": source_basis,
                            "final_ui": "not_applicable: no named terminal UI state is required",
                        },
                        "mapping_basis": (
                            f"Step {step} is part of the compound submission chain ending at durable "
                            f"step {spec['durable_step']}; the final MIME object and global order must pass."
                        ),
                    }
                )
        return sorted(result, key=lambda item: item["step"])

    @staticmethod
    def _read_simulator_info(udid: str) -> dict[str, Any]:
        proc = subprocess.run(
            ["xcrun", "simctl", "list", "devices", "--json"],
            check=False,
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode != 0:
            raise RuntimeError(f"simctl list failed: {proc.stderr.strip()}")
        payload = json.loads(proc.stdout)
        for runtime, rows in payload.get("devices", {}).items():
            if not isinstance(rows, list):
                continue
            for row in rows:
                if isinstance(row, dict) and row.get("udid") == udid:
                    return {
                        "name": str(row.get("name") or ""),
                        "deviceTypeIdentifier": str(
                            row.get("deviceTypeIdentifier") or ""
                        ),
                        "state": str(row.get("state") or ""),
                        "lastBootedAt": str(row.get("lastBootedAt") or ""),
                        "runtime": str(runtime),
                        "isAvailable": bool(row.get("isAvailable", True)),
                    }
        raise RuntimeError(f"Bound simulator UDID was not found: {udid}")

    @staticmethod
    def _read_app_health(*, udid: str, bundle_id: str) -> dict[str, Any]:
        evidence: dict[str, Any] = {
            "container_resolved": False,
            "metadata_bundle_matches": False,
            "preferences_found": False,
            "not_first_run": False,
            "next_uids_info_present": False,
            "next_uids_info_has_accounts": False,
        }
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, "data"],
            check=False,
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode != 0:
            evidence["error"] = proc.stderr.strip() or "get_app_container_failed"
            return evidence
        from platforms.ios.runtime_env.simulator_manager import remap_simulator_container_path
        container = remap_simulator_container_path(proc.stdout.strip(), udid)
        evidence["container_resolved"] = container.is_dir()
        evidence["data_container_path"] = str(container)
        if not container.is_dir():
            return evidence

        metadata_path = container / ".com.apple.mobile_container_manager.metadata.plist"
        if metadata_path.is_file():
            with metadata_path.open("rb") as handle:
                metadata = plistlib.load(handle)
            observed_bundle = str(metadata.get("MCMMetadataIdentifier") or "")
            evidence["metadata_bundle_id"] = observed_bundle
            evidence["metadata_bundle_matches"] = observed_bundle == bundle_id

        preferences_path = container / "Library" / "Preferences" / f"{bundle_id}.plist"
        evidence["preferences_found"] = preferences_path.is_file()
        if preferences_path.is_file():
            with preferences_path.open("rb") as handle:
                preferences = plistlib.load(handle)
            evidence["not_first_run"] = preferences.get("flutter.firstRun") is False
            next_uids = preferences.get("flutter.nextUidsInfo")
            evidence["next_uids_info_present"] = isinstance(next_uids, str) and bool(next_uids)
            accounts: list[str] = []
            if isinstance(next_uids, str) and next_uids:
                try:
                    outer = json.loads(next_uids)
                    inner_raw = outer.get("uidsByEmail") if isinstance(outer, dict) else None
                    inner = json.loads(inner_raw) if isinstance(inner_raw, str) else inner_raw
                    if isinstance(inner, dict):
                        accounts = sorted(str(key) for key in inner if str(key).strip())
                except json.JSONDecodeError:
                    accounts = []
            evidence["next_uids_accounts"] = accounts
            evidence["next_uids_info_has_accounts"] = bool(
                {SENDER_EMAIL, "benchsender@example.test"}.intersection(accounts)
            )
        return evidence

    @staticmethod
    def _fetch_mailbox_messages(
        *,
        api_base_url: str,
        recipient_email: str,
        mailbox: str = "INBOX",
    ) -> list[dict[str, Any]]:
        encoded_user = quote(recipient_email, safe="")
        encoded_mailbox = quote(mailbox, safe="")
        request = Request(
            f"{api_base_url}/api/user/{encoded_user}/messages/{encoded_mailbox}",
            method="GET",
        )
        try:
            with urlopen(request, timeout=5.0) as response:
                raw = response.read()
        except (HTTPError, URLError) as exc:
            raise RuntimeError(f"GET mailbox failed for {recipient_email}: {exc}") from exc
        payload = json.loads(raw.decode("utf-8"))
        if not isinstance(payload, list):
            raise RuntimeError(
                f"Mailbox payload for {recipient_email} must be a list, got {type(payload)!r}"
            )
        return [row for row in payload if isinstance(row, dict)]

    @staticmethod
    def _check_seed_messages(rows: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
        expected = {
            str(spec["source_subject"]): str(spec["source_message_id"])
            for spec in MESSAGE_SPECS
            if spec["source_subject"]
        }
        observed = {
            str(row.get("subject") or ""): MailyInstruction33Round9StateEvaluator._normalize_reference(
                row.get("Message-ID")
            )
            for row in rows
            if str(row.get("subject") or "") in expected
        }
        missing_or_wrong = {
            subject: message_id
            for subject, message_id in expected.items()
            if observed.get(subject)
            != MailyInstruction33Round9StateEvaluator._normalize_reference(message_id)
        }
        return {
            "name": "source_seed_messages",
            "steps": [1, 17, 34, 59, 68],
            "pass": not missing_or_wrong,
            "expected": expected,
            "observed": observed,
            "missing_or_wrong": missing_or_wrong,
        }

    @classmethod
    def _check_message(
        cls,
        *,
        spec: Mapping[str, Any],
        rows: Sequence[Mapping[str, Any]],
        booted_at: datetime,
        evaluation_cutoff: datetime,
    ) -> tuple[dict[str, Any], dict[str, Any] | None]:
        exact_subject_rows = [
            row for row in rows if str(row.get("subject") or "") == spec["subject"]
        ]
        parsed_rows: list[dict[str, Any]] = []
        parse_errors: list[str] = []
        for row in exact_subject_rows:
            try:
                parsed_rows.append(cls._parse_message(row))
            except Exception as exc:
                parse_errors.append(f"{type(exc).__name__}: {exc}")

        current_session = [
            parsed
            for parsed in parsed_rows
            if booted_at < parsed["date"] <= evaluation_cutoff
        ]
        observed_summary = [cls._message_summary(parsed) for parsed in parsed_rows]
        failures: list[str] = []
        if parse_errors:
            failures.append("mime_parse_error")
        if len(current_session) != 1:
            failures.append("current_session_exact_match_count")
            return (
                {
                    "name": f"message:{spec['key']}",
                    "steps": list(spec["steps"]),
                    "pass": False,
                    "failed_requirements": failures,
                    "expected_current_session_count": 1,
                    "observed_current_session_count": len(current_session),
                    "parse_errors": parse_errors,
                    "observed_candidates": observed_summary,
                },
                None,
            )

        parsed = current_session[0]
        expected_attachment = spec.get("attachment")
        if parsed["row_subject"] != spec["subject"] or parsed["header_subject"] != spec["subject"]:
            failures.append("subject")
        if parsed["from_addresses"] != [SENDER_EMAIL]:
            failures.append("sender")
        if parsed["to_addresses"] != [spec["mailbox"]]:
            failures.append("recipient")
        body = parsed["body"]
        if spec["body_mode"] == "exact" and body != spec["body"]:
            failures.append("body")
        elif spec["body_mode"] == "prefix" and not body.startswith(spec["body"]):
            failures.append("body")
        elif spec["body_mode"] == "contains" and spec["body"] not in body:
            failures.append("body")

        source_message_id = spec.get("source_message_id")
        if source_message_id:
            expected_reference = cls._normalize_reference(source_message_id)
            if parsed["in_reply_to"] != expected_reference:
                failures.append("in_reply_to")
            if parsed["references"] != expected_reference:
                failures.append("references")
            if str(spec["source_subject"]) not in body:
                failures.append("forwarded_or_quoted_source_subject")
        elif parsed["in_reply_to"] or parsed["references"]:
            failures.append("unexpected_source_reference")

        attachments = parsed["attachments"]
        if expected_attachment is None:
            if attachments:
                failures.append("unexpected_attachment")
        else:
            if len(attachments) != 1:
                failures.append("attachment_count")
            else:
                attachment = attachments[0]
                if attachment["content_type"] != expected_attachment["content_type"]:
                    failures.append("attachment_content_type")
                if attachment["sha256"] != expected_attachment["sha256"]:
                    failures.append("attachment_sha256")
                expected_filename = expected_attachment.get("filename")
                if expected_filename and attachment["filename"] != expected_filename:
                    failures.append("attachment_filename")

        if not isinstance(parsed["uid"], int) or parsed["uid"] <= 0:
            failures.append("uid")
        if not (booted_at < parsed["date"] <= evaluation_cutoff):
            failures.append("session_time_window")

        return (
            {
                "name": f"message:{spec['key']}",
                "steps": list(spec["steps"]),
                "pass": not failures,
                "failed_requirements": failures,
                "expected": {
                    "sender": SENDER_EMAIL,
                    "recipient": spec["mailbox"],
                    "subject": spec["subject"],
                    "body_mode": spec["body_mode"],
                    "body": spec["body"],
                    "source_subject": spec.get("source_subject"),
                    "source_message_id": source_message_id,
                    "attachment": expected_attachment,
                },
                "observed": cls._message_summary(parsed),
                "observed_candidate_count_all_sessions": len(parsed_rows),
                "observed_current_session_count": len(current_session),
            },
            parsed,
        )

    @staticmethod
    def _check_business_order(matched: Mapping[str, Mapping[str, Any]]) -> dict[str, Any]:
        durable_steps = [int(spec["durable_step"]) for spec in MESSAGE_SPECS]
        complete = all(spec["key"] in matched for spec in MESSAGE_SPECS)
        ordered_dates = [matched[spec["key"]]["date"] for spec in MESSAGE_SPECS if spec["key"] in matched]
        dates_strictly_increasing = complete and all(
            left < right for left, right in zip(ordered_dates, ordered_dates[1:])
        )
        per_mailbox: dict[str, list[dict[str, Any]]] = {}
        for spec in MESSAGE_SPECS:
            parsed = matched.get(spec["key"])
            if parsed is None:
                continue
            per_mailbox.setdefault(str(spec["mailbox"]), []).append(
                {
                    "key": spec["key"],
                    "durable_step": spec["durable_step"],
                    "uid": parsed["uid"],
                }
            )
        mailbox_uid_checks = {
            mailbox: all(
                left["uid"] < right["uid"]
                for left, right in zip(items, items[1:])
            )
            for mailbox, items in per_mailbox.items()
        }
        pass_value = complete and dates_strictly_increasing and all(mailbox_uid_checks.values())
        return {
            "name": "current_session_business_order",
            "steps": durable_steps,
            "pass": pass_value,
            "complete_nine_message_sequence": complete,
            "dates_strictly_increasing": dates_strictly_increasing,
            "ordered_dates": [value.isoformat() for value in ordered_dates],
            "per_mailbox_uid_order": mailbox_uid_checks,
            "per_mailbox_uids": per_mailbox,
        }

    @classmethod
    def _parse_message(cls, row: Mapping[str, Any]) -> dict[str, Any]:
        raw = str(row.get("mimeMessage") or "")
        if not raw:
            raise ValueError("missing mimeMessage")
        message = Parser(policy=policy.default).parsestr(raw)
        date_value = cls._parse_required_datetime(message.get("Date"), field="message.Date")
        body_parts: list[str] = []
        attachments: list[dict[str, Any]] = []
        for part in message.walk():
            if part.is_multipart():
                continue
            filename = part.get_filename()
            disposition = part.get_content_disposition()
            if disposition == "attachment" or filename is not None:
                payload = part.get_payload(decode=True) or b""
                attachments.append(
                    {
                        "filename": filename,
                        "content_type": part.get_content_type(),
                        "bytes": len(payload),
                        "sha256": hashlib.sha256(payload).hexdigest(),
                    }
                )
            elif part.get_content_type() == "text/plain":
                try:
                    body_parts.append(str(part.get_content()))
                except Exception:
                    payload = part.get_payload(decode=True) or b""
                    body_parts.append(payload.decode(part.get_content_charset() or "utf-8", errors="replace"))
        body = "\n".join(body_parts).replace("\r\n", "\n").replace("\r", "\n").strip()
        try:
            uid: int | str = int(row.get("uid"))
        except (TypeError, ValueError):
            uid = str(row.get("uid") or "")
        return {
            "uid": uid,
            "row_subject": str(row.get("subject") or ""),
            "header_subject": str(message.get("Subject") or ""),
            "from_addresses": [address for _, address in getaddresses(message.get_all("From", []))],
            "to_addresses": [address for _, address in getaddresses(message.get_all("To", []))],
            "date": date_value,
            "message_id": cls._normalize_reference(message.get("Message-ID")),
            "in_reply_to": cls._normalize_reference(message.get("In-Reply-To")),
            "references": cls._normalize_reference(message.get("References")),
            "body": body,
            "body_sha256": hashlib.sha256(body.encode("utf-8")).hexdigest(),
            "attachments": attachments,
        }

    @staticmethod
    def _message_summary(parsed: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "uid": parsed.get("uid"),
            "row_subject": parsed.get("row_subject"),
            "header_subject": parsed.get("header_subject"),
            "from_addresses": parsed.get("from_addresses"),
            "to_addresses": parsed.get("to_addresses"),
            "date": (
                parsed["date"].isoformat()
                if isinstance(parsed.get("date"), datetime)
                else parsed.get("date")
            ),
            "message_id": parsed.get("message_id"),
            "in_reply_to": parsed.get("in_reply_to"),
            "references": parsed.get("references"),
            "body_prefix": str(parsed.get("body") or "")[:240],
            "body_sha256": parsed.get("body_sha256"),
            "attachments": parsed.get("attachments"),
        }

    @staticmethod
    def _normalize_reference(value: Any) -> str:
        return re.sub(r"\s+", "", str(value or ""))

    @staticmethod
    def _parse_required_datetime(value: Any, *, field: str) -> datetime:
        raw = str(value or "").strip()
        if not raw:
            raise ValueError(f"{field} is missing")
        if field == "message.Date":
            parsed = parsedate_to_datetime(raw)
        else:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
